<style>
*{box-sizing:border-box}body{margin:0;color:#23324b;background:#f7f9fc;font-family:Inter,sans-serif}.cms-header{position:sticky;top:0;z-index:20;display:flex;align-items:center;min-height:70px;padding:10px max(24px,calc((100vw - 1180px)/2));border-bottom:1px solid #e6ebf2;background:#fff}.cms-brand img{display:block;max-width:190px;max-height:48px}.cms-nav{display:flex;align-items:center;gap:5px;margin-left:auto}.cms-nav a{display:block;padding:10px 12px;color:#40516b;text-decoration:none;font-size:14px;font-weight:600;border-radius:6px}.cms-nav a:hover{color:#397ef6;background:#f0f5ff}.cms-nav-item{position:relative}.cms-dropdown{position:absolute;top:100%;left:0;display:none;min-width:200px;padding:7px;border:1px solid #e3e8f0;border-radius:8px;background:#fff;box-shadow:0 12px 30px rgba(30,45,70,.12)}.cms-nav-item:hover .cms-dropdown{display:block}.cms-dropdown a{white-space:nowrap}.caret{margin-left:3px}.cms-menu-toggle{display:none;margin-left:auto;border:0;background:transparent;font-size:24px}.cms-main{width:min(1120px,calc(100% - 36px));min-height:calc(100vh - 205px);margin:0 auto;padding:38px 0 60px}.cms-template-full-width{width:calc(100% - 36px);max-width:1500px}.cms-template-landing{width:100%;max-width:none;padding-top:0}.cms-breadcrumb{display:flex;gap:8px;margin-bottom:18px;color:#8490a3;font-size:12px}.cms-breadcrumb a{color:#397ef6;text-decoration:none}.cms-article{padding:34px 42px;border:1px solid #e4e9f1;border-radius:12px;background:#fff;box-shadow:0 7px 24px rgba(29,45,70,.05)}.cms-article h1{margin:0 0 28px;color:#182640;font-size:34px;line-height:1.2}.cms-content{color:#4d5e75;font-size:16px;line-height:1.75}.cms-content img{max-width:100%;height:auto}.cms-content h2,.cms-content h3{margin-top:1.7em;color:#21314a}.cms-home-hero{padding:100px 32px;text-align:center}.cms-home-hero span{color:#397ef6;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.cms-home-hero h1{margin:17px 0;color:#17253e;font-size:54px}.cms-home-hero p{max-width:720px;margin:auto;color:#66768d;font-size:18px;line-height:1.7}.cms-footer{display:grid;grid-template-columns:1fr auto;gap:10px;padding:28px max(24px,calc((100vw - 1180px)/2));color:#9ba7b9;background:#17243a;font-size:12px}.cms-footer strong{display:block;color:#fff;font-size:15px}.cms-footer span{display:block;margin-top:5px}.cms-footer nav{display:flex;gap:18px}.cms-footer a{color:#d5dce7;text-decoration:none}.cms-footer small{grid-column:1/-1;padding-top:16px;border-top:1px solid rgba(255,255,255,.1)}@media(max-width:800px){.cms-header{min-height:62px}.cms-nav{position:absolute;top:100%;right:16px;left:16px;display:none;align-items:stretch;flex-direction:column;padding:9px;border:1px solid #e3e8f0;border-radius:8px;background:#fff;box-shadow:0 12px 30px rgba(30,45,70,.12)}.cms-nav.open{display:flex}.cms-menu-toggle{display:block}.cms-dropdown{position:static;display:block;margin-left:14px;border:0;box-shadow:none}.cms-article{padding:24px}.cms-home-hero{padding:70px 10px}.cms-home-hero h1{font-size:38px}.cms-footer{grid-template-columns:1fr}.cms-footer nav{flex-wrap:wrap}}
</style>
